import {resolveQueueParish} from './parish-queue-scope.js';
import {reportDateOnly} from './parish-report-print.js?v=20261106-styled-dialogs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function registerDate(row,keys) {
 const [year,month,day]=keys.map(key=>row[key]);
 const monthNames=['January','February','March','April','May','June','July','August','September','October','November','December'];
 const monthNumber=Number(month);
 const label=Number.isInteger(monthNumber)&&monthNumber>=1&&monthNumber<=12?monthNames[monthNumber-1]:String(month||'');
 return [label,day,year].filter(value=>value!==null&&value!==undefined&&String(value).trim()!=='').join(' ')||'Not recorded';
}
export function buildRecordReport({parish,records,config,labels={},filters={},date=new Date().toISOString()}) {
 const value=(row,key)=>key==='created_at'||key==='marriage_date'?reportDateOnly(row[key]):row[key]===null||row[key]===undefined||row[key]===''?'Not recorded':typeof row[key]==='object'?JSON.stringify(row[key]):String(row[key]);
 const used=new Set(['id',config.name]);
 const columns=[{label:'Record No.',get:row=>value(row,'id')},{label:'Name',get:row=>value(row,config.name)}];
 for(const [keys,label]of [[['year_baptism','month_batism','date_batism'],'Baptism date'],[['year_confirm','month_confirm','date_baptism'],'Confirmation date'],[['year_birth','month_birth','day_birth'],'Birth date']]) {
  if(!config.fields.includes(keys[0]))continue;keys.forEach(key=>used.add(key));columns.push({label,get:row=>registerDate(row,keys)});
 }
 for(const key of ['marriage_date','party_role','location','minister'])if(config.fields.includes(key)){used.add(key);columns.push({label:labels[key]||key,get:row=>value(row,key)});}
 const extra=config.fields.filter(key=>!used.has(key));
 const search=String(filters.search||'').trim();
 const filterLabels=[filters.year?'Year: '+filters.year:'All years',filters.month?'Month: '+(/^\d+$/.test(String(filters.month))?new Date(2020,Number(filters.month)-1,1).toLocaleString('en-US',{month:'long'}):filters.month):'All months',search?'Search ('+(filters.searchBy||'all fields')+'): '+search:'No search filter'];
 const table='<div class="register-wrap"><table><thead><tr><th scope="col">No.</th>'+columns.map(column=>'<th scope="col">'+esc(column.label)+'</th>').join('')+'</tr></thead><tbody>'+records.map((row,index)=>'<tr><td>'+(index+1)+'</td>'+columns.map(column=>'<td>'+esc(column.get(row))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
 const details=extra.length&&records.length?'<section class="record-details"><h2>Additional register details</h2>'+records.map((row,index)=>'<article class="record-detail"><h3><span>'+String(index+1).padStart(2,'0')+'</span> '+esc(value(row,config.name))+' <small>Record No. '+esc(value(row,'id'))+'</small></h3><dl>'+extra.map(key=>'<div><dt>'+esc(labels[key]||key.replace(/_/g,' '))+'</dt><dd>'+esc(value(row,key))+'</dd></div>').join('')+'</dl></article>').join('')+'</section>':'';
 const filename=(String(config.title||'parish-records').replace(/[^a-z0-9-]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'parish-records')+'-report.html';
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(config.title)} | Parish Records Report</title><style>
 @page{size:A4 landscape;margin:14mm}*{box-sizing:border-box}body{margin:0;background:#eef3f8;color:#23415a;font:13px/1.55 'Segoe UI',Arial,sans-serif}.report-toolbar{position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 24px;background:#fff;border-bottom:1px solid #d3e2ee;box-shadow:0 2px 8px #123b670a}.report-toolbar strong{font-size:14px;color:#193b5c}.actions{display:flex;gap:10px;flex-wrap:wrap}.actions button{padding:10px 16px;min-height:42px;border:1px solid #bdd6e9;border-radius:10px;background:#f3f9ff;color:#1762a2;font:600 13px 'Segoe UI',Arial,sans-serif;cursor:pointer}.actions .primary{color:#fff;border-color:#0054cf;background:linear-gradient(125deg,#007db8,#0054cf)}button:focus-visible{outline:2px solid #0054cf;outline-offset:3px}main{width:min(1120px,calc(100% - 40px));margin:28px auto;padding:38px;background:#fff;border:1px solid #d4e2ee;border-top:5px solid #007ed4;border-radius:14px;box-shadow:0 10px 32px #123b670b}.report-header{padding-bottom:24px;border-bottom:1px solid #d5e2ed}.eyebrow{margin:0 0 7px;font-size:10px;font-weight:700;letter-spacing:.15em;color:#5681a2}h1{margin:0 0 8px;color:#173e63;font-size:25px;line-height:1.3}.report-title{margin:0;font-size:16px;font-weight:600;color:#40617e}.report-meta{display:flex;flex-wrap:wrap;gap:12px 28px;margin-top:18px;font-size:12px;color:#667f94}.report-meta strong{color:#23415a}.filters{padding:12px 16px;margin:20px 0;background:#f1f7fd;border:1px solid #d7e6f2;border-radius:8px;font-size:12px;color:#4d6981}.register-wrap{overflow-x:auto;border:1px solid #cedfeb;border-radius:8px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:10px 9px;text-align:left;vertical-align:top;border-right:1px solid #e0e9f0;border-bottom:1px solid #e0e9f0;overflow-wrap:anywhere}th:last-child,td:last-child{border-right:0}tbody tr:last-child td{border-bottom:0}thead{display:table-header-group}th{background:#eaf3fc;color:#315777;font-size:11px;font-weight:700}th:first-child{width:38px}tbody tr:nth-child(even){background:#f8fbfe}tr{break-inside:avoid}h2{margin:28px 0 14px;font-size:17px;color:#193e63;break-after:avoid}.record-detail{margin-bottom:14px;border:1px solid #d6e3ee;border-radius:10px;overflow:hidden}.record-detail h3{margin:0;padding:12px 16px;background:#f1f7fc;color:#234f73;font-size:13px;break-after:avoid}.record-detail h3 span{color:#6f91ac;margin-right:8px}.record-detail h3 small{float:right;font-size:11px;font-weight:400;color:#7890a5}dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;margin:0}dl div{padding:12px 16px;border-top:1px solid #e1eaf2;break-inside:avoid;min-width:0}dt{font-size:10px;color:#6f879b;margin-bottom:4px}dd{margin:0;font-size:12px;color:#25465f;overflow-wrap:anywhere;white-space:pre-wrap}footer{margin-top:26px;padding-top:14px;border-top:1px solid #d5e2ed;font-size:10px;color:#8194a5}.empty{padding:28px;border:1px dashed #bdd6ea;border-radius:8px;background:#f7fbff;text-align:center;color:#667f94}
 @media(max-width:700px){.report-toolbar{align-items:flex-start;flex-direction:column;padding:14px 16px}main{width:calc(100% - 24px);margin:16px auto;padding:20px}.register-wrap table{min-width:740px}dl{grid-template-columns:repeat(2,minmax(0,1fr))}.record-detail h3 small{float:none;display:block;margin-top:4px}}@media print{body{background:#fff;font-size:10px}.report-toolbar{display:none!important}main{width:100%;margin:0;padding:0;border:0;border-radius:0;box-shadow:none}.report-header{padding-bottom:15px}h1{font-size:20px}.filters{margin:14px 0}.register-wrap{overflow:visible;border-radius:0}.register-wrap table{min-width:0;width:100%;table-layout:fixed;font-size:9px}th,td{padding:6px;font-size:9px}th:first-child{width:25px}th:nth-child(2){width:70px}th:nth-child(3){width:140px}dl{grid-template-columns:repeat(3,minmax(0,1fr))}.record-detail{overflow:visible;border-radius:0}.record-detail h3{font-size:11px}dd{font-size:10px}footer{font-size:9px}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
 </style></head><body><div class="report-toolbar"><strong>Record report preview</strong><div class="actions"><button class="primary" type="button" data-print>Print / Save as PDF</button><button type="button" data-download>Download report</button><button type="button" data-close>Close</button></div></div><main><header class="report-header"><p class="eyebrow">PARISH RECORDS</p><h1>${esc(parish)}</h1><p class="report-title">${esc(config.title)}</p><div class="report-meta"><span>Report date: <strong>${esc(reportDateOnly(date))}</strong></span><span>Total: <strong>${records.length} record(s)</strong></span></div></header><div class="filters">${filterLabels.map(esc).join(' &middot; ')}</div>${records.length?table:'<p class="empty">No records match these filters.</p>'}${details}<footer>Prepared from the parish record register. Dates are shown without time.</footer></main><script>
 document.querySelector('[data-print]').addEventListener('click',()=>window.print());
 document.querySelector('[data-close]').addEventListener('click',()=>window.close());
 document.querySelector('[data-download]').addEventListener('click',()=>{const blob=new Blob(['<!doctype html>',document.documentElement.outerHTML],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=${JSON.stringify(filename)};document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 </script></body></html>`;
}
export async function previewRecordReport({records,config,labels,filters,session,request,previewWindow}) {
 const popup=previewWindow||window.open('','_blank','width=1100,height=800');
 if(!popup){await window.parishDialogs.alert('Please allow the record preview window, then try again.');return;}
 if(popup.closed)return;
 popup.document.open();popup.document.write('<!doctype html><title>Record report preview</title><p style="font:14px Arial;padding:24px">Preparing record report...</p>');popup.document.close();
 try {
  const parish=await resolveQueueParish(session,(table,query)=>request('/rest/v1/'+table+'?'+query,{accessToken:session.accessToken}));
  if(popup.closed)return;
  popup.document.open();popup.document.write(buildRecordReport({parish:parish.parish_name,records,config,labels,filters}));popup.document.close();popup.focus();
 }catch(error){if(!popup.closed)popup.document.body.textContent='Could not prepare record report: '+error.message;}
}